final readonly class DiscountPolicy
{
    public function apply(int $subtotalCents, bool $firstOrder): int
    {
        $percent = match (true) {
            $firstOrder => 15,
            $subtotalCents > 10_000 => 10,   // above $100
            default => 0,
        };

        return $subtotalCents - intdiv($subtotalCents * $percent, 100);
    }
}

