#[ORM\Entity]
class Order
{
    private const MAX_LINES = 20;

    #[ORM\OneToMany(targetEntity: OrderLine::class, mappedBy: 'order',
        cascade: ['persist'], orphanRemoval: true)]
    private Collection $lines;

    #[ORM\Column(enumType: OrderStatus::class)]
    private OrderStatus $status = OrderStatus::Draft;

    public function addLine(ProductId $product, int $qty, Money $price): void
    {
        if ($this->status !== OrderStatus::Draft) {
            throw new OrderAlreadyConfirmed($this->id);
        }
        if ($this->lines->count() >= self::MAX_LINES) {
            throw new TooManyLines(self::MAX_LINES);
        }
        $this->lines->add(new OrderLine($this, $product, $qty, $price));
    }

    public function confirm(): void
    {
        if ($this->lines->isEmpty()) {
            throw new CannotConfirmEmptyOrder($this->id);
        }
        $this->status = OrderStatus::Confirmed;
    }
}

